import{B,C,read,circle}from'../ten-utils.js';
export default({g,p,extra,t})=>{let mode=extra.mode??0;if(mode===0){let metal=['Zn','Fe','Cu','Ag'][p[0]],react=p[0]<2;g.box(0,.1,0,.7,.7,.5);g.box(0,-.1,0,.13,.65,.08,C.dark);for(let i=0;i<18;i++){let a=i*2.5;g.sphere(Math.sin(a+t*.2)*.55,Math.cos(i*4+t*.15)*.55,Math.sin(i)*.3,.04,C.blue)}if(react)for(let i=0;i<12;i++)g.sphere(Math.sin(i)*.11,Math.cos(i*3)*.5,.12,.045,'#c99167');g.text(0,-1,0,B(`${metal} in CuSO4`,`${metal}, CuSO4 में`));return[read('Metal','धातु',metal),read('Copper displaced','कॉपर का विस्थापन',react?B('Yes: more reactive than Cu','हाँ: Cu से अधिक सक्रिय'):B('No','नहीं'))]}
 if(mode===1){let f=p[0]/100;g.sphere(-.7,0,0,.22,C.gold,'Na');g.sphere(.7,0,0,.27,C.green,'Cl');circle(g,-.7,0,.4,C.dark);circle(g,.7,0,.45,C.dark);for(let i=0;i<7;i++){let a=(i<4?i:i+1)*Math.PI*2/8;g.sphere(.7+.45*Math.cos(a),.45*Math.sin(a),0,.035,C.blue)}g.sphere(-.3+f*.55,0,0,.05,C.blue,B('electron','इलेक्ट्रॉन'));if(f===1){g.text(-.7,-.7,0,'Na+');g.text(.7,-.7,0,'Cl−');g.line([-.4,.7,0],[.4,.7,0],C.gold,3)}return[read('Transferred outer electron','स्थानांतरित बाहरी इलेक्ट्रॉन',f===1?1:0),read('Result at completion','पूरा होने पर परिणाम',B('Oppositely charged ions attract','विपरीत आवेश वाले आयन आकर्षित होते हैं'))]}
 let coating=p[0]/100;g.box(0,0,0,.85,.18,.3,C.dark);for(let i=0;i<30;i++){let x=-.8+(i%15)*.115,z=i<15?-.25:.25;g.sphere(x,-.22,z,.05,i<coating*30?C.green:'#c68960')}g.text(0,-.85,0,B('Barrier coating reduces exposure','अवरोधक परत संपर्क घटाती है'));return[read('Coated area','ढका क्षेत्र',p[0],'%'),read('Exposed area','खुला क्षेत्र',100-p[0],'%'),read('Model','मॉडल',B('Qualitative, not a corrosion-rate prediction','गुणात्मक, संक्षारण-दर का पूर्वानुमान नहीं'))]};
